	@Test
	void namespaceGrowthRefusalKeepsAdmittedCoordinatesAndRetiresAfterTheirLastConsumer() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(3_200L, 3_200L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			KernelResultCoordinates coordinates = KernelResultCoordinates.open(ledger, 1,
					new int[] { 0 }, new int[] { 0 }, 1L, 2, 0);
			assertThat(coordinates).isNotNull();
			try (coordinates) {
				long firstNamespace = coordinates.newNamespace();
				assertThat(firstNamespace).isEqualTo(2L);
				for (int namespace = 1; namespace < 8; namespace++) {
					assertThat(coordinates.newNamespace()).isEqualTo(namespace + 2L);
				}

				coordinates.set(0, 8L, 9L, 10L, 0L, firstNamespace);
				coordinates.emit();
				coordinates.requestRetirement(firstNamespace);
				long admittedBytes = ledger.usedBytes();
				assertThat(coordinates.newNamespace()).isZero();
				assertThat(coordinates.enabled()).isTrue();
				assertThat(ledger.usedBytes()).isEqualTo(admittedBytes);

				long[] copied = new long[KernelResultCoordinates.WIDTH];
				assertThat(coordinates.coordinate(0, 0, copied)).isTrue();
				assertThat(copied).containsExactly(8L, 9L, 10L, 0L, firstNamespace);

				List<Long> retired = new ArrayList<>();
				coordinates.drainRetiredNamespaces(retired::add);
				assertThat(retired).isEmpty();
				coordinates.releaseRow(0);
				coordinates.drainRetiredNamespaces(retired::add);
				assertThat(retired).isEmpty();
				coordinates.clear(0);
				coordinates.drainRetiredNamespaces(retired::add);
				assertThat(retired).containsExactly(firstNamespace);
			}
			assertThat(ledger.usedBytes()).isZero();
		}
		assertThat(manager.usedBytes()).isZero();
	}

