	@Test
	void repeatedNamespacesAndOutOfOrderReleasesKeepWindowOriginsAndChangeMasks() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(100_000L, 100_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelResultCoordinates coordinates = KernelResultCoordinates.open(ledger, 2,
						new int[] { 0, 1 }, new int[] { 3, 5 }, 3L, 4, 1)) {
			assertThat(coordinates).isNotNull();
			long namespaceA = coordinates.newNamespace();
			long namespaceB = coordinates.newNamespace();
			coordinates.set(0, 10L, 11L, 12L, 13L, namespaceA);
			coordinates.set(1, 20L, 21L, 22L, 23L, namespaceA);
			int frame = coordinates.newFrame();
			coordinates.save(frame);
			coordinates.emit();

			coordinates.set(0, 30L, 31L, 32L, 33L, namespaceB);
			coordinates.clear(1);
			coordinates.emit();
			coordinates.restore(frame, 1L);
			coordinates.emit();
			coordinates.restore(frame, 2L);
			coordinates.emit();
			coordinates.requestRetirement(namespaceA);
			coordinates.requestRetirement(namespaceB);
			coordinates.clear(0);
			coordinates.clear(1);
			coordinates.releaseFrame(frame);

			assertThat(coordinates.changedSlots(0)).isEqualTo((1L << 3) | (1L << 5));
			assertThat(coordinates.changedSlots(1)).isEqualTo((1L << 3) | (1L << 5));
			assertThat(coordinates.changedSlots(2)).isEqualTo(1L << 3);
			assertThat(coordinates.changedSlots(3)).isEqualTo(1L << 5);
			long[] copied = new long[KernelResultCoordinates.WIDTH];
			assertThat(coordinates.coordinate(0, 1, copied)).isTrue();
			assertThat(copied).containsExactly(20L, 21L, 22L, 23L, namespaceA);
			assertThat(coordinates.hasCoordinate(1, 1)).isFalse();
			assertThat(coordinates.coordinate(2, 0, copied)).isTrue();
			assertThat(copied).containsExactly(10L, 11L, 12L, 13L, namespaceA);
			assertThat(coordinates.coordinate(3, 1, copied)).isTrue();
			assertThat(copied).containsExactly(20L, 21L, 22L, 23L, namespaceA);

			coordinates.releaseRow(1);
			coordinates.releaseRow(1);
			assertThatThrownBy(coordinates::beginFill).isInstanceOf(IllegalStateException.class)
					.hasMessage("coordinate batch still has unconsumed rows");
			coordinates.releaseRow(2);
			coordinates.releaseRow(3);
			List<Long> retired = new ArrayList<>();
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).isEmpty();
			coordinates.releaseRow(0);
			coordinates.releaseRow(0);
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).containsExactlyInAnyOrder(namespaceA, namespaceB);
			assertThat(coordinates.enabled()).isTrue();

			coordinates.beginFill();
			long next = coordinates.newNamespace();
			coordinates.set(0, 40L, 41L, 42L, 43L, next);
			coordinates.emit();
			coordinates.requestRetirement(next);
			coordinates.clear(0);
			coordinates.releaseRow(0);
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).containsExactlyInAnyOrder(namespaceA, namespaceB, next);
		}
		assertThat(manager.usedBytes()).isZero();
	}

	@Test
	void windowPinsSurviveCollisionDeletionAndNamespaceDirectoryGrowth() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(100_000L, 100_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelResultCoordinates coordinates = KernelResultCoordinates.open(ledger, 1,
						new int[] { 0 }, new int[] { 0 }, 1L, 2, 0)) {
			assertThat(coordinates).isNotNull();
			long predecessor = coordinates.newNamespace();
			long namespaceA;
			List<Long> retired = new ArrayList<>();
			do {
				namespaceA = coordinates.newNamespace();
				assertThat(namespaceA).isPositive();
				if (namespaceBucket(namespaceA) != namespaceBucket(predecessor)) {
					coordinates.requestRetirement(namespaceA);
					coordinates.drainRetiredNamespaces(retired::add);
				}
			} while (namespaceBucket(namespaceA) != namespaceBucket(predecessor));
			long namespaceB = coordinates.newNamespace();
			coordinates.set(0, 1L, 2L, 3L, 4L, namespaceA);
			coordinates.emit();
			coordinates.set(0, 5L, 6L, 7L, 8L, namespaceB);
			coordinates.emit();
			coordinates.clear(0);
			coordinates.requestRetirement(namespaceA);
			coordinates.requestRetirement(namespaceB);
			coordinates.requestRetirement(predecessor);
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).contains(predecessor).doesNotContain(namespaceA, namespaceB);

			// Keep enough unrelated namespaces live together to force a directory resize, then retire them.
			List<Long> unrelated = new ArrayList<>();
			for (int i = 0; i < 12; i++) {
				long namespace = coordinates.newNamespace();
				assertThat(namespace).isPositive();
				unrelated.add(namespace);
			}
			for (long namespace : unrelated) {
				coordinates.requestRetirement(namespace);
			}
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).containsAll(unrelated).doesNotContain(namespaceA, namespaceB);
			long[] copied = new long[KernelResultCoordinates.WIDTH];
			assertThat(coordinates.coordinate(0, 0, copied)).isTrue();
			assertThat(copied).containsExactly(1L, 2L, 3L, 4L, namespaceA);
			assertThat(coordinates.coordinate(1, 0, copied)).isTrue();
			assertThat(copied).containsExactly(5L, 6L, 7L, 8L, namespaceB);
			coordinates.releaseRow(1);
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).doesNotContain(namespaceA, namespaceB);
			coordinates.releaseRow(0);
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).contains(namespaceA, namespaceB);
			assertThat(coordinates.enabled()).isTrue();
		}
		assertThat(manager.usedBytes()).isZero();
	}

