	@Test
	void collisionChainRemovalsKeepLaterNamespaceAllocationsUsable() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(100_000L, 100_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelResultCoordinates coordinates = KernelResultCoordinates.open(ledger, 1,
						new int[] { 0 }, new int[] { 0 }, 1L, 1, 0)) {
			assertThat(coordinates).isNotNull();
			long anchor = coordinates.newNamespace();
			List<Long> colliding = new ArrayList<>();
			List<Long> retired = new ArrayList<>();
			int attempts = 0;
			while (colliding.size() < 3 && attempts++ < 10_000) {
				long namespace = coordinates.newNamespace();
				assertThat(namespace).isPositive();
				if (namespaceBucket(namespace) == namespaceBucket(anchor)) {
					colliding.add(namespace);
				} else {
					coordinates.requestRetirement(namespace);
					coordinates.drainRetiredNamespaces(retired::add);
				}
			}
			assertThat(colliding).hasSize(3);

			coordinates.requestRetirement(colliding.get(1));
			coordinates.drainRetiredNamespaces(retired::add);
			coordinates.requestRetirement(colliding.get(0));
			coordinates.drainRetiredNamespaces(retired::add);
			coordinates.requestRetirement(colliding.get(2));
			coordinates.drainRetiredNamespaces(retired::add);
			coordinates.requestRetirement(anchor);
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).contains(colliding.get(1), colliding.get(0), colliding.get(2), anchor);

			long afterCollisionRemoval = coordinates.newNamespace();
			assertThat(afterCollisionRemoval).isGreaterThan(colliding.get(2));
			coordinates.requestRetirement(afterCollisionRemoval);
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).contains(afterCollisionRemoval);
		}
		assertThat(manager.usedBytes()).isZero();
	}

